/**
 * KS-740 — the batch TSA path must be BOUNDED.
 *
 * Kam ruled option A on 2026-09-02 ("Bound the TSA path"): a per-request timeout
 * and a concurrency limit, with `maxItems: 100` and the published contract
 * unchanged. These tests pin both halves of that ruling.
 *
 * They are written to FAIL against the previous implementation:
 *   - the fan-out was a bare `Promise.all` over up to 100 items, so peak
 *     concurrency equalled the batch size;
 *   - the TSA call was a bare `fetch` with no `signal`, so a hanging upstream
 *     was bounded by nothing.
 */
import { describe, expect, it, vi, afterEach } from 'vitest';

import { mapWithConcurrency } from '../index';

describe('KS-740 — mapWithConcurrency bounds the fan-out', () => {
  it('never exceeds the limit, and that is measured at the peak, not inferred', async () => {
    const LIMIT = 4;
    const items = Array.from({ length: 25 }, (_, i) => i);
    let inFlight = 0;
    let peak = 0;

    await mapWithConcurrency(items, LIMIT, async (n) => {
      inFlight += 1;
      peak = Math.max(peak, inFlight);
      // Yield so the scheduler can actually overlap workers — without this the
      // whole thing could serialise and the test would pass for the wrong reason.
      await new Promise((r) => setTimeout(r, 1));
      inFlight -= 1;
      return n;
    });

    expect(peak).toBeLessThanOrEqual(LIMIT);
    // The control: the work MUST have overlapped, or "peak <= limit" is vacuous.
    // A serial implementation would give peak 1 and pass the assertion above
    // while bounding nothing.
    expect(peak).toBeGreaterThan(1);
  });

  it('preserves input order regardless of completion order', async () => {
    // Deliberately invert the timing: later items finish first. If results were
    // pushed on completion rather than written by index, this returns reversed.
    const items = [40, 30, 20, 10];
    const out = await mapWithConcurrency(items, 4, async (ms) => {
      await new Promise((r) => setTimeout(r, ms));
      return ms;
    });
    expect(out).toEqual([40, 30, 20, 10]);
  });

  it('a slow item costs only its own slot — it does not stall the whole batch', async () => {
    // This is why the implementation is a shared cursor rather than chunked
    // Promise.all: chunking makes every item wait for the slowest in its chunk.
    const items = [50, 1, 1, 1, 1, 1, 1, 1];
    const finished: number[] = [];
    await mapWithConcurrency(items, 4, async (ms, ) => {
      await new Promise((r) => setTimeout(r, ms));
      finished.push(ms);
      return ms;
    });
    // The 50 ms item must NOT be among the first finishers.
    expect(finished[0]).toBe(1);
    expect(finished[finished.length - 1]).toBe(50);
  });

  it('a limit above the item count does not over-spawn workers', async () => {
    let started = 0;
    await mapWithConcurrency([1, 2], 100, async (n) => {
      started += 1;
      return n;
    });
    expect(started).toBe(2);
  });

  it('an empty batch is a no-op, not a hang', async () => {
    await expect(mapWithConcurrency([], 4, async (n) => n)).resolves.toEqual([]);
  });
});

describe('KS-740 — the TSA request carries a deadline', () => {
  afterEach(() => {
    vi.unstubAllGlobals();
    vi.resetModules();
  });

  it('passes an AbortSignal to fetch — the bare-fetch shape is the defect', async () => {
    // Capture what the client actually hands to fetch. Before KS-740 there was
    // no `signal` key at all, so this assertion is the red-proof.
    const seen: RequestInit[] = [];
    vi.stubGlobal('fetch', async (_url: string, init: RequestInit) => {
      seen.push(init);
      // Fail fast with a shape the client handles; the assertion is on `init`.
      return { ok: false, status: 503, statusText: 'unavailable' } as Response;
    });

    const { submitTimestampRequest } = await import('../tsa/rfc3161-client');
    await submitTimestampRequest('https://tsa.example.test/tsr', Buffer.from([0x30, 0x00]));

    expect(seen).toHaveLength(1);
    expect(seen[0]?.signal).toBeDefined();
    expect(seen[0]?.signal).toBeInstanceOf(AbortSignal);
  });

  it('reports a timeout AS a timeout, not as a generic failure', async () => {
    vi.stubGlobal('fetch', async () => {
      const err = new Error('The operation was aborted');
      err.name = 'TimeoutError';
      throw err;
    });

    const { submitTimestampRequest } = await import('../tsa/rfc3161-client');
    const res = await submitTimestampRequest('https://tsa.example.test/tsr', Buffer.from([0x30, 0x00]));

    expect(res.success).toBe(false);
    // "TSA request failed: The operation was aborted" reads like our bug.
    // Naming the deadline is the difference between a page and a shrug.
    expect(res.error).toMatch(/timed out after \d+ms/);
    expect(res.error).toContain('tsa.example.test');
  });
  it('RED KS-753: POST /api/timestamps and /api/timestamps/batch answer 201 with verified true for the mock TSA fallback when no TSA is reachable - the mock is reported as verified today', async () => {
    vi.stubGlobal('fetch', async () => ({ ok: false, status: 503, statusText: 'unavailable' } as Response));
    const nodeCrypto = await import('crypto');
    const { privateKey, publicKey } = nodeCrypto.generateKeyPairSync('rsa', { modulusLength: 2048 });
    const b64url = (s: string | Buffer) => Buffer.from(s).toString('base64url');
    const signingInput = b64url(JSON.stringify({ alg: 'RS256', typ: 'JWT' })) + '.' + b64url(JSON.stringify({ userId: 'u-ks753', email: 'ks753@secuura.io', role: 'user', verificationLevel: 'email', exp: Math.floor(Date.now() / 1000) + 300 }));
    const bearer = 'Bearer ' + signingInput + '.' + b64url(nodeCrypto.sign('sha256', Buffer.from(signingInput), privateKey));
    const savedEnv = { JWT_PUBLIC_KEY: process.env.JWT_PUBLIC_KEY, PORT: process.env.PORT };
    process.env.JWT_PUBLIC_KEY = Buffer.from(publicKey.export({ type: 'spki', format: 'pem' }).toString()).toString('base64');
    process.env.PORT = '0';
    vi.doMock('../db', () => ({ initDb: async () => false, isDbAvailable: () => false, query: async () => ({ rows: [], rowCount: 0 }), closeDb: async () => undefined }));
    vi.resetModules();
    const { default: app } = await import('../index');
    const drive = (url: string, body: unknown) => new Promise<any>((resolve) => {
      const headers: Record<string, unknown> = {};
      const req: any = { method: 'POST', url, headers: { authorization: bearer }, body };
      const res: any = { statusCode: 200, locals: {}, on: () => res, status: (c: number) => { res.statusCode = c; return res; }, json: (b: unknown) => { resolve({ status: res.statusCode, body: b }); return res; } };
      res.send = res.json;
      res.end = () => res.json(null);
      res.setHeader = (k: string, v: unknown) => { headers[k.toLowerCase()] = v; return res; };
      res.getHeader = (k: string) => headers[k.toLowerCase()];
      res.removeHeader = (k: string) => { delete headers[k.toLowerCase()]; };
      app(req, res, () => resolve({ status: -1, body: null }));
    });
    const single = await drive('/api/timestamps', { hash: 'a'.repeat(64), timestampType: 'rfc3161' });
    const batch = await drive('/api/timestamps/batch', { hashes: [{ hash: 'b'.repeat(64) }, { hash: 'c'.repeat(64) }], timestampType: 'rfc3161' });
    for (const k of ['JWT_PUBLIC_KEY', 'PORT'] as const) { if (savedEnv[k] === undefined) delete process.env[k]; else process.env[k] = savedEnv[k]; }
    const shape = (t: any) => [t.eidasQualified, JSON.parse(Buffer.from(t.proof, 'base64').toString()).mock, t.verified];
    expect([single.status, single.body.error, batch.status, batch.body.error]).toEqual([201, undefined, 201, undefined]);
    expect([shape(single.body.data), batch.body.data.timestamps.map(shape)]).toEqual([[false, true, true], [[false, true, true], [false, true, true]]]);
  });
});
